psql -v ON_ERROR_STOP=1 -q <<'EOF'
DROP INDEX IF EXISTS orders_status_date_idx;
CREATE INDEX orders_status_date_idx ON orders (status, order_date) INCLUDE (order_id);
VACUUM ANALYZE orders;
EOF
psql -c "EXPLAIN (ANALYZE, BUFFERS) $(sed 's/;\s*$//' target_query.sql)" 2>&1 | grep -E "orders|Execution|Index|Bitmap|Seq"

python3 - <<'EOF'
p='/work/solution.sql'
s=open(p).read()
s=s.replace('''--    * orders(status, order_date): serves the target query's filter directly.''','''--    * orders(status, order_date) INCLUDE (order_id): serves the target query's
--      filter and the join key from the index alone (index-only scan). The
--      INCLUDE column is what makes the planner prefer the index over a seq scan.''')
s=s.replace('''CREATE INDEX orders_status_date_idx ON orders (status, order_date);''','''CREATE INDEX orders_status_date_idx ON orders (status, order_date) INCLUDE (order_id);''')
s=s.replace('''ANALYZE customers;
ANALYZE products;
ANALYZE orders;
ANALYZE order_items;''','''-- VACUUM sets the visibility map so index-only scans avoid heap fetches.
VACUUM ANALYZE customers;
VACUUM ANALYZE products;
VACUUM ANALYZE orders;
VACUUM ANALYZE order_items;''')
open(p,'w').write(s)
EOF
psql -v ON_ERROR_STOP=1 -q -f solution.sql 2>&1 | grep -v NOTICE; echo "exit=${PIPESTATUS[0]}"; psql -c "EXPLAIN (ANALYZE, BUFFERS) $(sed 's/;\s*$//' target_query.sql)" 2>&1 | grep -E "on orders|Execution|Planning Time"; psql -Atc "select 'orders',count(*) from orders union all select 'order_items',count(*) from order_items union all select 'customers',count(*) from customers union all select 'products',count(*) from products"
